import { test, expect } from '@playwright/test';

// The knowledge map is a levelled set of data flow diagrams: a context diagram,
// one level-1 diagram of the apps, and a level-2 and level-3 diagram per app
// that has been decomposed. Every diagram below level 0 is generated by
// scripts/build-dfd.cjs, so these tests assert the navigation rather than the
// wording of any one bubble.
test.describe('Knowledge Map and Viewer', () => {
  test('drills from the context diagram to level 1 and into an app', async ({ page }) => {
    await page.goto('/knowledge/DFD_LEVEL0.html');
    await expect(page.locator('h1')).toContainText('Context Diagram');

    await page.locator('a[href="DFD_LEVEL1.html"]').first().click();
    await expect(page.locator('h1')).toContainText('Level 1', { timeout: 10000 });

    await page.locator('a[href="DFD_LEVEL2_YIELDCURVES.html"]').first().click();
    await expect(page.locator('h1')).toContainText('Yield Curves', { timeout: 10000 });
  });

  test('reaches a process spec from a level-2 bubble', async ({ page }) => {
    await page.goto('/knowledge/DFD_LEVEL2_YIELDCURVES.html');

    // 3.3 Adjust for other effects. Its bubble opens the spec named for it, whose title is the process name.
    await page.locator('a.process[href*="3.3_Adjust_For_Other_Effects.md"]').first().click();
    await expect(page).toHaveURL(/3\.3_Adjust_For_Other_Effects\.md/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText('3.3 Adjust for other effects');
  });

  test('drills from an ingestion job to its Level 3 page, its process spec, and back up', async ({ page }) => {
    await page.goto('/knowledge/DFD_LEVEL2_INGESTION.html');

    // 1.3 Calculate yield curve data sets: the bubble opens the job's Level 3 page, not the spec.
    await page.locator('a.process[href="DFD_LEVEL3_INGEST_YIELDCURVEDATA.html"]').click();
    await expect(page).toHaveURL(/DFD_LEVEL3_INGEST_YIELDCURVEDATA(\.html)?$/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText('1.3 Calculate yield curve data sets');

    // The one process there opens the process spec, and the spec's up link returns to this Level 3 page.
    await page.locator('a.process[href*="1.3_Calculate_Yield_Curve_Data_Sets.md"]').click();
    await expect(page).toHaveURL(/1\.3_Calculate_Yield_Curve_Data_Sets\.md/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText('1.3 Calculate yield curve data sets');
    const upLink = page.locator('#up-link');
    await expect(upLink).toContainText('Up to Level 3 DFD', { timeout: 15000 });
    await upLink.click();
    await expect(page).toHaveURL(/DFD_LEVEL3_INGEST_YIELDCURVEDATA(\.html)?$/, { timeout: 10000 });

    // The Level 3 header returns to Level 2.
    await page.locator('.nav-header a', { hasText: 'Level 2' }).click();
    await expect(page).toHaveURL(/DFD_LEVEL2_INGESTION(\.html)?$/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText('1 Acquire and derive reference data');
  });

  test('every ingestion job has a Level 3 page that opens its spec and is the page its spec points up to', async ({ page, request }) => {
    await page.goto('/knowledge/DFD_LEVEL2_INGESTION.html');
    const hrefs = await page.locator('a.process').evaluateAll(els => els.map(a => a.getAttribute('href')));
    expect(hrefs).toHaveLength(15);

    for (const href of hrefs) {
      expect(href, 'a job bubble opens its Level 3 page').toMatch(/^DFD_LEVEL3_INGEST_[A-Z]+\.html$/);
      const diagram = await request.get('/knowledge/' + href);
      expect(diagram.ok(), href).toBe(true);
      const html = await diagram.text();
      expect(html, href + ' returns to Level 2').toContain('href="DFD_LEVEL2_INGESTION.html"');
      const spec = /<a class="process" href="viewer\.html#\/md\/knowledge\/(1\.\d+_[A-Za-z_]+\.md)/.exec(html);
      expect(spec, href + ' has a process that opens a process spec').not.toBeNull();

      const md = await request.get('/knowledge/' + spec[1]);
      expect(md.ok(), spec[1]).toBe(true);
      const specifies = (await md.text()).split('\n').find(l => l.startsWith('**Specifies:**'));
      expect(specifies, spec[1] + ' points up to ' + href).toContain('(/knowledge/' + href.replace('.html', '') + ')');
    }
  });

  test('reaches the parent spec from a diagram header', async ({ page }) => {
    await page.goto('/knowledge/DFD_LEVEL3_YC_LOAD.html');
    await expect(page.locator('h1')).toContainText('3.1');

    await page.locator('a.spec-link').click();
    await expect(page).toHaveURL(/3\.1_Parse_Sources_And_Calculate_Yields\.md/, { timeout: 10000 });
  });

  test('a leaf process spec names the code that implements it', async ({ page }) => {
    await page.goto('/knowledge/viewer.html#/md/YieldCurves/knowledge/3.1_Parse_Sources_And_Calculate_Yields.md');
    const body = page.locator('#content');
    await expect(body).toContainText('parseRefCpiAndSaFactors', { timeout: 15000 });
    await expect(body).toContainText('Specifies:');
    await expect(body).toContainText('Implemented by:');
  });

  test('a process spec up link is relative to the viewer, so it works on a project site', async ({ page }) => {
    await page.goto('/knowledge/viewer.html#/md/knowledge/1.1_Download_FedInvest_Prices.md');
    const upLink = page.locator('#up-link');
    await expect(upLink).toBeVisible({ timeout: 15000 });
    await expect(upLink).toContainText('Up to Level 3 DFD');

    // A root-absolute href would leave /Treasuries/ on a project site.
    const raw = await upLink.getAttribute('href');
    expect(raw.startsWith('/')).toBe(false);
    const resolved = await upLink.evaluate(a => new URL(a.getAttribute('href'), location.href).pathname);
    expect(resolved).toMatch(/\/knowledge\/DFD_LEVEL3_INGEST_FEDINVEST\.html$/);

    await upLink.click();
    // The local server may redirect the .html away; the page that loads is the diagram either way.
    await expect(page).toHaveURL(/\/knowledge\/DFD_LEVEL3_INGEST_FEDINVEST(\.html)?$/, { timeout: 10000 });
    await expect(page.locator('h1')).toContainText('1.1', { timeout: 10000 });
  });

  test('toggles a CSV preview in the Data Dictionary', async ({ page }) => {
    await page.goto('/knowledge/viewer.html#/md/knowledge/DATA_DICTIONARY.md');

    const viewLink = page.locator('a:has-text("View Preview")').first();
    await expect(viewLink).toBeVisible({ timeout: 10000 });
    await viewLink.click();

    // The container appears at once and then holds either the parsed table or
    // an error, depending on whether the browser can reach the store.
    const container = page.locator('.csv-preview-container');
    await expect(container).toBeVisible({ timeout: 10000 });
    await expect(container.locator('.csv-preview, p')).toBeVisible({ timeout: 15000 });

    if (await page.locator('.csv-preview').isVisible()) {
      await viewLink.click();
      await expect(page.locator('.csv-preview')).not.toBeVisible();
    }
  });

  test('follows an internal link inside a rendered mermaid diagram', async ({ page }) => {
    // knowledge/tests/fixtures/MermaidLink.md is a fixture: no spec carries a Mermaid diagram, so
    // this test exercises only the viewer's Mermaid click-through wiring.
    await page.goto('/knowledge/viewer.html#/md/knowledge/tests/fixtures/MermaidLink.md');

    const mermaidSvg = page.locator('.mermaid svg');
    await expect(mermaidSvg).toBeVisible({ timeout: 15000 });

    const link = page.locator('.mermaid a').first();
    await link.click();

    // The target is whatever the diagram currently points at; what matters is
    // that the click loads another document rather than leaving the viewer.
    await expect(page).toHaveURL(/#\/md\/.+\.md/, { timeout: 10000 });
    await expect(page).not.toHaveURL(/MermaidLink\.md$/);
    await expect(page.locator('#content h1')).toBeVisible({ timeout: 10000 });
  });

  test('renders LaTeX math via KaTeX, not raw source', async ({ page }) => {
    await page.goto('/knowledge/viewer.html#/md/YieldCurves/knowledge/3.2_Adjust_For_Seasonality.md');

    const katex = page.locator('.katex').first();
    await expect(katex).toBeVisible({ timeout: 15000 });

    const body = await page.locator('#content').innerText();
    expect(body).not.toContain('\\frac');
    expect(body).not.toContain('P_{SA}');
  });

  test('shows an error for a file that does not exist', async ({ page }) => {
    await page.goto('/knowledge/viewer.html#/md/knowledge/NonExistent.md');
    await expect(page.locator('.error')).toBeVisible();
    await expect(page.locator('.error')).toContainText('Failed to load');
  });
});
